/**
 * @import {ColumnMetaData, FileMetaData, MetadataOptions} from '../src/types.js'
 */

import { parquetMetadataAsync } from './metadata.js'

/**
 * @typedef {object} ParquetColumnSummary
 * @property {string} name
 * @property {string} type
 * @property {number} numValues
 * @property {number | null} nullCount
 * @property {number} compressedBytes
 * @property {number} uncompressedBytes
 * @property {number} chunks
 * @property {string[]} encodings
 * @property {string[]} codecs
 */

/**
 * Summarize each column across all row groups.
 * Columns are merged by dotted path, in order of first appearance.
 * The null count is null unless every chunk of the column records one.
 * Chunks without meta_data are ignored.
 *
 * @param {FileMetaData} metadata
 * @param {{ columns?: string[] }} [options] top-level column names to keep, all if undefined
 * @returns {ParquetColumnSummary[]}
 */
export function parquetColumnSummary(metadata, { columns } = {}) {
  const wanted = columns && new Set(columns)
  /** @type {Map<string, ParquetColumnSummary & { encodingSet: Set<string>, codecSet: Set<string> }>} */
  const summaries = new Map()
  for (const { columns: chunks } of metadata.row_groups) {
    for (const { meta_data } of chunks) {
      if (!meta_data) continue
      if (wanted && !wanted.has(meta_data.path_in_schema[0])) continue
      const name = meta_data.path_in_schema.join('.')
      let summary = summaries.get(name)
      if (!summary) {
        summary = {
          name,
          type: meta_data.type,
          numValues: 0,
          nullCount: 0,
          compressedBytes: 0,
          uncompressedBytes: 0,
          chunks: 0,
          encodings: [],
          codecs: [],
          encodingSet: new Set(),
          codecSet: new Set(),
        }
        summaries.set(name, summary)
      }
      summary.numValues += Number(meta_data.num_values)
      summary.compressedBytes += Number(meta_data.total_compressed_size)
      summary.uncompressedBytes += Number(meta_data.total_uncompressed_size)
      summary.chunks++
      for (const encoding of meta_data.encodings ?? []) summary.encodingSet.add(encoding)
      if (meta_data.codec !== undefined) summary.codecSet.add(meta_data.codec)
      const nulls = meta_data.statistics?.null_count
      if (nulls === undefined) summary.nullCount = null
      else if (summary.nullCount !== null) summary.nullCount += Number(nulls)
    }
  }
  return [...summaries.values()].map(({ encodingSet, codecSet, ...summary }) => ({
    ...summary,
    encodings: [...encodingSet].sort(),
    codecs: [...codecSet].sort(),
  }))
}

/**
 * Read the footer of a file and summarize its columns.
 *
 * @param {MetadataOptions & { file: import('../src/types.js').AsyncBuffer, columns?: string[], initialFetchSize?: number }} options
 * @returns {Promise<ParquetColumnSummary[]>}
 */
export async function parquetColumnSummaryAsync({ file, columns, ...metadataOptions }) {
  const metadata = await parquetMetadataAsync(file, metadataOptions)
  return parquetColumnSummary(metadata, { columns })
}
